use vstd::prelude::*;

verus! {
    // A character is a digit iff it lies between '0' and '9' inclusive.
    spec fn is_digit(c: char) -> bool {
        c >= '0' && c <= '9'
    }

    // A sequence of characters consists entirely of digits iff
    // every index in range satisfies is_digit.
    spec fn all_digits(s: seq<char>) -> bool {
        forall |j: int| 0 <= j && j < s.len() ==> is_digit(s[j])
    }

    // Checks whether the Vec<char> 'text' consists entirely of decimal digits.
    // Returns true exactly when all_digits(text@) holds.
    fn is_integer(text: &Vec<char>) -> (result: bool)
        ensures
            result == all_digits(text@)
    {
        let mut i: usize = 0;
        // We scan from i = 0 up to text.len().
        // Invariant 1: i never exceeds text.len().
        // Invariant 2: for all processed positions k < i, text@[k] is a digit.
        while i < text.len()
            invariant
                i <= text.len(),
                forall |k: int| 0 <= k && k < (i as int) ==> is_digit(text@[k]),
            decreases text.len() - i
        {
            // Safe to unwrap because i < text.len().
            let c: char = *text.get(i).unwrap();
            // If we find a non‐digit, we can prove all_digits(text@) is false
            // by witnessing the violating index i, and then return false.
            if c < '0' || c > '9' {
                assert(!all_digits(text@)) by {
                    // at index i, is_digit fails
                    assert(!is_digit(text@[i as int]));
                };
                return false;
            }
            // Otherwise, record that position i is a digit, to maintain the invariant.
            assert(is_digit(text@[i as int]));
            i = i + 1;
        }
        // If we scanned the whole array without finding a non‐digit, it's all digits.
        true
    }
}

